package com.example.service;

import org.springframework.ai.document.Document;

import java.util.List;

/**
 * Thin abstraction over the Spring AI {@link org.springframework.ai.vectorstore.VectorStore}.
 * Isolates the vector store implementation from the rest of the application,
 * making it easy to swap ChromaDB for another vector store if needed.
 */
public interface VectorStoreService {

    /**
     * Stores documents (with their embeddings generated by Spring AI internally).
     *
     * @param documents documents to store
     */
    void store(List<Document> documents);

    /**
     * Runs a similarity search and returns matching documents filtered by similarity threshold.
     *
     * @param query               the search query
     * @param maxResults          maximum number of candidate results
     * @param similarityThreshold minimum similarity score threshold (0.0 to 1.0)
     * @return list of matching documents ordered by relevance
     */
    List<Document> similaritySearch(String query, int maxResults, double similarityThreshold);

    /**
     * Runs a similarity search and returns the top matching documents.
     *
     * @param query the search query
     * @param topK  maximum number of results
     * @return list of matching documents ordered by relevance
     */
    List<Document> similaritySearch(String query, int topK);

    /**
     * Deletes documents from the vector store by their IDs.
     *
     * @param ids vector document IDs to delete
     */
    void delete(List<String> ids);
}
